// Filter out non-text updates (stickers, photos, voice, etc) and bot self-messages.
// We only handle text messages for translation.

const item = $input.first();
const body = item.json || {};
const msg = body.message || {};
const text = msg.text || '';
const from = msg.from || {};
const chat = msg.chat || {};
const updateId = body.update_id;

if (!text || typeof text !== 'string' || text.trim().length === 0) {
  return [{ json: { skipped: true, reason: 'no-text-content', updateId } }];
}
if (from.is_bot) {
  return [{ json: { skipped: true, reason: 'sender-is-bot', updateId } }];
}
// Skip bot commands like /start /help by default.
if (text.startsWith('/')) {
  return [{ json: { skipped: true, reason: 'bot-command', updateId } }];
}

return [{ json: {
  updateId,
  userId: from.id != null ? String(from.id) : 'unknown',
  chatId: chat.id != null ? String(chat.id) : null,
  userLabel: from.username ? '@' + from.username : (from.first_name || 'user-' + from.id),
  text,
  raw: body,
}}];

// Per-user-id sliding-window rate limit, opt-in. Default 60 / 5 min / user.
// Skipped items pass through without consuming a token.

if ($env.RATE_LIMIT_ENABLED !== '1') {
  return $input.all();
}

const LIMIT = 60;
const WINDOW_MS = 5 * 60 * 1000;
const MAX_KEYS = 5000;

const data = $getWorkflowStaticData('global');
data.rateBuckets = data.rateBuckets || {};
const buckets = data.rateBuckets;
const now = Date.now();

for (const k of Object.keys(buckets)) {
  buckets[k] = (buckets[k] || []).filter(t => now - t < WINDOW_MS);
  if (buckets[k].length === 0) delete buckets[k];
}
if (Object.keys(buckets).length > MAX_KEYS) {
  const oldest = Object.entries(buckets).sort((a, b) => (a[1][0] || 0) - (b[1][0] || 0)).slice(0, 100);
  for (const [k] of oldest) delete buckets[k];
}

const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  if (j.skipped) { out.push(item); continue; }
  const key = 'user:' + j.userId;
  const hits = buckets[key] || [];
  if (hits.length >= LIMIT) {
    out.push({ json: { ...j, skipped: true, reason: 'rate-limit', limit: LIMIT } });
    continue;
  }
  buckets[key] = [...hits, now];
  out.push(item);
}
return out;

// 5-minute idempotency window on Telegram update_id, opt-in.
// Telegram retries on 5xx so dedup is important.

const crypto = require('crypto');

if ($env.IDEMPOTENCY_ENABLED !== '1') {
  return $input.all();
}

const WINDOW_MS = 5 * 60 * 1000;
const MAX_KEYS = 5000;

const data = $getWorkflowStaticData('global');
data.seenUpdates = data.seenUpdates || {};
const seen = data.seenUpdates;
const now = Date.now();

for (const k of Object.keys(seen)) {
  if (now - seen[k] > WINDOW_MS) delete seen[k];
}
if (Object.keys(seen).length > MAX_KEYS) {
  const oldest = Object.entries(seen).sort((a, b) => a[1] - b[1]).slice(0, 500);
  for (const [k] of oldest) delete seen[k];
}

const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  if (j.skipped) { out.push(item); continue; }
  const updateId = j.updateId;
  if (updateId == null) { out.push(item); continue; }
  const key = String(updateId);
  if (seen[key]) {
    out.push({ json: { ...j, skipped: true, reason: 'duplicate-update-id', dedupKey: key } });
    continue;
  }
  seen[key] = now;
  out.push(item);
}
return out;

// Redis variant for clustered n8n:
// const result = await redis.set('tg-idem:' + updateId, '1', 'EX', 300, 'NX');
// if (result === null) skip;

// Build the LLM prompt and select the provider. Default openai.

const targetLang = $env.TARGET_LANG || 'English';
const provider = ($env.LLM_PROVIDER || 'openai').toLowerCase();

const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  if (j.skipped) { out.push(item); continue; }
  const userText = String(j.text || '').slice(0, 3000); // hard cap to keep tokens bounded
  const systemPrompt = 'You are a translation engine. Detect the source language of the user message, then translate to ' + targetLang + '. Output ONLY the translated text, no preamble, no quotes, no language label. Preserve emojis and basic punctuation. Keep code blocks unchanged. If the source is already ' + targetLang + ', return the original text verbatim.';
  out.push({ json: { ...j, provider, systemPrompt, userText } });
}
return out;

// Normalize OpenAI vs Anthropic response shape into one stable schema.
// OpenAI: choices[0].message.content
// Anthropic: content[0].text

const items = $input.all();
const out = [];
for (const item of items) {
  const j = item.json || {};
  if (j.skipped) { out.push(item); continue; }

  let reply = '';
  if (j.choices && Array.isArray(j.choices) && j.choices.length > 0) {
    reply = (j.choices[0].message && j.choices[0].message.content) || '';
  } else if (j.content && Array.isArray(j.content) && j.content.length > 0) {
    reply = j.content[0].text || '';
  } else if (j.translatedText) {
    reply = j.translatedText;
  }

  if (!reply || typeof reply !== 'string') {
    out.push({ json: { ...j, skipped: true, reason: 'empty-llm-response' } });
    continue;
  }

  // Pull through chat metadata from the upstream Set Provider node.
  // Item could be either upstream OpenAI OR Anthropic, both paths set $json before LLM.
  // The merge for chat metadata happens via the $('Set Provider') call which preserves
  // the original userId / chatId regardless of which branch ran.
  let chatId, userId, userLabel;
  try {
    const setProvider = $('Set Provider').first();
    if (setProvider && setProvider.json) {
      chatId = setProvider.json.chatId;
      userId = setProvider.json.userId;
      userLabel = setProvider.json.userLabel;
    }
  } catch (e) { /* fallback empty */ }

  out.push({ json: {
    skipped: false,
    chatId: chatId || j.chatId || null,
    userId: userId || j.userId || null,
    userLabel: userLabel || j.userLabel || null,
    replyText: reply.trim(),
  }});
}
return out;

// LLM Fallback Reply.
// Discriminate between LLM error (provider returned an error envelope) and
// router error (typo in LLM_PROVIDER -> Switch fallback path).
// Critical: do NOT JSON.stringify(errorRaw) blindly, because that can leak
// the full systemPrompt + userText into a structured log.

const input = $input.first();
const raw = input.json || {};
const errorRaw = raw.error || raw;
const isLlmError = !!(errorRaw && (errorRaw.message || errorRaw.code || (errorRaw.error && errorRaw.error.message)));
let errorMessage;
if (isLlmError) {
  errorMessage = (errorRaw.message) || (errorRaw.error && errorRaw.error.message) || ('LLM error code ' + (errorRaw.code || '?'));
} else {
  // Router fallback (provider unknown). Log without stringifying the prompt.
  errorMessage = 'Unknown provider value: "' + (raw.provider || 'undefined') + '". Set LLM_PROVIDER to openai or anthropic.';
}

// Pull chat-id from the Set Provider node which we know ran for non-skipped items.
let chatId = null, userId = null, userLabel = null;
try {
  const setProvider = $('Set Provider').first();
  if (setProvider && setProvider.json) {
    chatId = setProvider.json.chatId;
    userId = setProvider.json.userId;
    userLabel = setProvider.json.userLabel;
  }
} catch (e) { /* fallback empty */ }

const fallbackText = 'Sorry, the translator is having trouble right now. Please try again in a few seconds.';

return [{ json: {
  chatId,
  userId,
  userLabel,
  replyText: fallbackText,
  llmError: { message: errorMessage, isLlmError },
  at: new Date().toISOString(),
}}];

// Error Fallback for the Telegram Reply send-failure path.
// Build a structured ops log so the LLM Fallback Reply path stays user-facing
// while ops gets a Slack alert about the underlying delivery failure.

const input = $input.first();
const raw = input.json || {};
const errorRaw = raw.error || raw;
const isHttpError = !!(errorRaw && (errorRaw.message || errorRaw.code));
const errorMessage = isHttpError ? (errorRaw.message || 'Telegram send error') : 'Unknown reply-send error';

// Pull chat metadata for the alert body. Fall back gracefully if missing.
let chatId = null, userId = null, userLabel = null;
try {
  const setProvider = $('Set Provider').first();
  if (setProvider && setProvider.json) {
    chatId = setProvider.json.chatId;
    userId = setProvider.json.userId;
    userLabel = setProvider.json.userLabel;
  }
} catch (e) { /* ignore */ }

return [{ json: {
  telegramReplyError: { message: errorMessage, raw: errorRaw },
  chat: { chatId, userId, userLabel },
  at: new Date().toISOString(),
}}];
